def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    pairs = []
    for r in range(h):
        for c in range(w):
            value = grid[r][c]
            if value == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == value:
                    pairs.append((r, c, dr, dc, value))
    for r, c, dr, dc, value in pairs:
        # Extend each end of a same-color diagonal pair through background.
        for rr, cc, step_r, step_c in ((r, c, -dr, -dc), (r + dr, c + dc, dr, dc)):
            rr += step_r
            cc += step_c
            while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                out[rr][cc] = value
                rr += step_r
                cc += step_c
    return out
